static void garagedoor_unit_eventqueue_init(garagedoor_unit_eventqueue * eq, garagedoor_unit_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer garagedoor_unit_eventqueue_size(garagedoor_unit_eventqueue * eq)
{
	return eq->size;
}

static garagedoor_unit_event garagedoor_unit_eventqueue_pop(garagedoor_unit_eventqueue * eq)
{
	garagedoor_unit_event event;
	if(garagedoor_unit_eventqueue_size(eq) <= 0) {
		garagedoor_unit_event_init(&event, GarageDoor_Unit_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean garagedoor_unit_eventqueue_push(garagedoor_unit_eventqueue * eq, garagedoor_unit_event ev)
{
	if(garagedoor_unit_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void garagedoor_unit_event_init(garagedoor_unit_event * ev, GarageDoor_UnitEventID name)
{
	ev->name = name;
}

static void garageDoor_Unit_add_event_to_queue(garagedoor_unit_eventqueue * eq, GarageDoor_UnitEventID name)
{
	garagedoor_unit_event event;
	garagedoor_unit_event_init(&event, name);
	garagedoor_unit_eventqueue_push(eq, event);
}

